// Padded with extra grass at the top so the sidewalk's fixed masking
// zone never eats into the real roof/AC-unit content — only margin. The
// right-edge tree-lined path column is patched separately in that same
// padding zone with a clean, tree-free paver strip (sampled from the gap
// between the photo's own first two trees) instead of the plain grass
// tile, because the photo's very first tree was already cut off at its
// own top edge — tiling that fragment upward duplicated a half-tree.
// Removing it there means the first tree the player actually sees is a
// complete one.
//
// A full-width band of plain grass, sampled well clear of the roof line,
// used to repeat-tile the ground downward on the rare screen tall enough
// that the box's depth exceeds the photo at its natural (never-shrunk)
// scale.
export const PENTHOUSE_LOT_GROUND_STRIP_TOP = 140;
export const PENTHOUSE_LOT_GROUND_STRIP_HEIGHT = 25;
